const input = $input.first();
const items = (input?.json?.data ?? []).slice(0,5);
const headlines = items.map((a, i) => `${i+1}. ${a.title}`);
const message = `📰 *Daily News Roundup* 📰

${headlines.join('
')}

📊 *Summary:*
• Total headlines: ${headlines.length}
• Source: TheNewsAPI.com
• Time: ${new Date().toLocaleString()}

🔗 *Read more:* [TheNewsAPI.com](https://thenewsapi.com)`;
return [{ json: { message, headlines, totalHeadlines: headlines.length, timestamp: new Date().toISOString(), success: true } }];

// Log successful execution
const executionData = $input.first().json;

console.log('✅ News automation completed successfully');
console.log(`📊 Headlines sent: ${executionData.totalHeadlines || 0}`);
console.log(`⏰ Execution time: ${new Date().toLocaleString()}`);

// Return success data for logging
return [{
  json: {
    status: 'success',
    message: 'News automation completed successfully',
    headlinesSent: executionData.totalHeadlines || 0,
    executionTime: new Date().toISOString(),
    workflowName: 'Scheduled News Automation'
  }
}];
